namespace OpenEMR\Modules\AgentForge\Services;

use Firebase\JWT\JWT;
use Firebase\JWT\Key;
use OpenEMR\Common\Acl\AclMain;
use OpenEMR\Core\OEGlobalsBag;

class AgentJwtService {
    private string $secretKey;
    private int $ttlSeconds = 300; // 5 minutes

    public function mintToken(int $userId, int $patientId, bool $breakglassFlag, ?string $breakglassReason): string {
        $payload = [
            'iss' => 'openemr-agentforge',
            'sub' => (string)$userId,
            'patient_id' => $patientId,
            'role' => $this->getUserRole($userId),
            'breakglass_flag' => $breakglassFlag,
            'breakglass_reason' => $breakglassReason,
            'iat' => time(),
            'exp' => time() + $this->ttlSeconds
        ];

        return JWT::encode($payload, $this->secretKey, 'HS256');
    }

    private function getUserRole(int $userId): string {
        // Query GACL for user's role
        return AclMain::getUserRole($userId);
    }
}
```

