public function turn(Request $request): StreamedResponse|JsonResponse
{
    $session = $request->getSession();

    // Validate patient context
    $patientId = $session->get('pid');
    if ($patientId === null || $patientId === '') {
        $this->logger->warning('Agent turn attempted without patient context', [
            'user_id' => $session->get('authUserID'),
        ]);
        return $this->jsonError('No patient context - open a patient chart first', 400);
    }

    // Validate user authentication
    $userId = $session->get('authUserID');
    if ($userId === null) {
        return $this->jsonError('Not authenticated', 401);
    }

    // Parse request body for breakglass info
    $body = json_decode($request->getContent(), true, 512, JSON_THROW_ON_ERROR);
    $breakglassFlag = (bool) $session->get('breakglass_flag', false);
    $breakglassReason = $body['breakglass_reason'] ?? null;

    // Mint JWT with all context
    $jwt = $this->jwtService->mintToken(
        (int) $userId,
        (int) $patientId,
        $breakglassFlag,
        $breakglassReason,
    );

    // Proxy implementation in next subtask
}
