```php
private const SIDECAR_TIMEOUT_SECONDS = 120;

public function turn(Request $request): StreamedResponse|JsonResponse
{
    // ... session validation and JWT minting from subtask 2 ...

    $messageContent = $body['message'] ?? '';
    if ($messageContent === '') {
        return $this->jsonError('Message content required', 400);
    }

    return new StreamedResponse(
        function () use ($jwt, $messageContent, $patientId): void {
            $this->proxyToSidecar($jwt, $messageContent, (int) $patientId);
        },
        200,
        [
            'Content-Type' => 'text/event-stream',
            'Cache-Control' => 'no-cache',
            'X-Accel-Buffering' => 'no',
        ]
    );
}

private function proxyToSidecar(string $jwt, string $message, int $patientId): void
{
    $ch = curl_init($this->sidecarBaseUrl . '/agent/turn');
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_HTTPHEADER => [
            'Authorization: Bearer ' . $jwt,
            'Content-Type: application/json',
        ],
        CURLOPT_POSTFIELDS => json_encode([
            'message' => $message,
            'patient_id' => $patientId,
        ], JSON_THROW_ON_ERROR),
        CURLOPT_TIMEOUT => self::SIDECAR_TIMEOUT_SECONDS,
        CURLOPT_WRITEFUNCTION => function ($ch, $chunk) {
            echo $chunk;
            if (ob_get_level() > 0) {
                ob_flush();
            }
            flush();
            return strlen($chunk);
        },
    ]);

    $success = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $error = curl_error($ch);
    curl_close($ch);

    if (!$success || $httpCode >= 400) {
        $this->logger->error('Sidecar proxy failed', [
            'http_code' => $httpCode,
            'error' => $error,
        ]);
        echo "event: error\ndata: {\"error\": \"Agent service unavailable\"}\n\n";
    }
}
```

Handle connection refused, timeout, and HTTP error responses gracefully. Always send SSE-formatted error events so client can display user-friendly messages.

