from ..gateway.auth_gateway import RequestContext

class DemographicsTool:
    def __init__(self, openemr_base_url: str, redis_client):
        self.base_url = openemr_base_url
        self.redis = redis_client
        self.timeout = 2.0  # seconds

    async def execute(self, ctx: RequestContext) -> ToolResult:
        start = time.monotonic()

        cache_key = f'tool:demographics:{ctx.patient_id}'
        cached = await self.redis.get(cache_key)
        if cached:
            return ToolResult.from_cached(cached)

        try:
            async with httpx.AsyncClient(timeout=self.timeout) as client:
                resp = await client.get(
                    f'{self.base_url}/apis/fhir/r4/Patient/{ctx.patient_id}',
                    headers={'Authorization': f'Bearer {ctx.api_token}'}
                )

            if resp.status_code == 200:
                data = resp.json()
                result = self._parse_fhir_patient(data)
                await self.redis.setex(cache_key, 60, result.to_json())
                return result
            elif resp.status_code == 403:
                return ToolResult(tool='get_demographics', status='permission_denied', ...)
        except httpx.TimeoutException:
            return ToolResult(tool='get_demographics', status='timeout', ...)

        return ToolResult(tool='get_demographics', latency_ms=int((time.monotonic()-start)*1000), ...)
