public function searchNotes(Request $request): JsonResponse {
    $patientId = $request->get('patient_id');
    $query = $request->get('query');
    $limit = min($request->get('limit', 5), 10);

    $this->validateAgentJwt($request);

    // FULLTEXT search scoped by patient_id first
    // The pid filter runs BEFORE fulltext, keeping it fast
    $sql = "
        SELECT id, date, title, 
               MATCH(body) AGAINST (? IN NATURAL LANGUAGE MODE) AS score,
               SUBSTRING(body, 1, 200) as snippet
        FROM pnotes
        WHERE pid = ? AND MATCH(body) AGAINST (? IN NATURAL LANGUAGE MODE)

        UNION ALL

        SELECT id, date, codetext as title,
               MATCH(description) AGAINST (? IN NATURAL LANGUAGE MODE) AS score,
               SUBSTRING(description, 1, 200) as snippet
        FROM form_clinical_notes
        WHERE pid = ? AND MATCH(description) AGAINST (? IN NATURAL LANGUAGE MODE)

        ORDER BY score DESC LIMIT ?
    ";

    $results = QueryUtils::fetchRecords($sql, [
        $query, $patientId, $query,
        $query, $patientId, $query,
        $limit
    ]);

    return new JsonResponse(['results' => $results]);
}
