public function searchNotes(Request $request): JsonResponse
{
    $this->validateAgentJwt($request);

    $patientId = $request->get('patient_id');
    $query = $request->get('query');
    $limit = $request->get('limit', 5);

    // Input validation - reject invalid types early
    if (!is_numeric($patientId) || (int)$patientId <= 0) {
        return new JsonResponse(['error' => 'Invalid patient_id'], 400);
    }
    if (!is_string($query) || strlen($query) < 2 || strlen($query) > 200) {
        return new JsonResponse(['error' => 'Query must be 2-200 characters'], 400);
    }
    if (!is_numeric($limit)) {
        $limit = 5;
    }

    $service = new NoteSearchService();
    $results = $service->searchPatientNotes((int)$patientId, $query, (int)$limit);

    return new JsonResponse(['results' => $results]);
}
```

