import hmac
import hashlib
from langfuse import Langfuse

class AgentLangfuse:
    def __init__(self, langfuse_url: str, hmac_key: bytes):
        self.langfuse = Langfuse(
            host=langfuse_url,
            public_key=os.environ['LANGFUSE_PUBLIC_KEY'],
            secret_key=os.environ['LANGFUSE_SECRET_KEY']
        )
        self.hmac_key = hmac_key

    def pseudonymize_id(self, raw_id: int) -> str:
        """HMAC-SHA256 pseudonymization. Not reversible without key."""
        return hmac.new(
            self.hmac_key,
            str(raw_id).encode(),
            hashlib.sha256
        ).hexdigest()[:16]

    def trace_turn(
        self,
        user_id: int,
        patient_id: int,
        breakglass_flag: bool,
        tool_calls: list[dict],
        latency_ms: int
    ):
        trace = self.langfuse.trace(
            name='agent_turn',
            user_id=self.pseudonymize_id(user_id),
            metadata={
                'patient_id_hash': self.pseudonymize_id(patient_id),
                'breakglass_flag': breakglass_flag,  # boolean only
                # NO breakglass_reason - that's PHI-adjacent
            }
        )

        for tc in tool_calls:
            trace.span(
                name=tc['tool'],
                metadata={
                    'status': tc['status'],
                    'latency_ms': tc['latency_ms'],
                    'cache_hit': tc['cache_hit'],
                    # NO args or results - those contain PHI
                }
            )

        return trace
