import re

class IdentityGuard:
    """Detects attempts to query about different patient mid-session."""

    PATIENT_REFERENCE_PATTERNS = [
        r'\b(?:patient|pt\.?)\s+([A-Z][a-z]+\s+[A-Z][a-z]+)',
        r'\bMRN\s*[:#]?\s*(\d+)',
        r'\b(?:room|bed)\s+(\d+[A-Za-z]?)',
    ]

    def __init__(self, current_patient_name: str, current_mrn: str):
        self.current_name = current_patient_name.lower()
        self.current_mrn = current_mrn

    def check_message(self, message: str) -> tuple[bool, str | None]:
        """Returns (is_valid, error_message_if_invalid)."""

        for pattern in self.PATIENT_REFERENCE_PATTERNS:
            match = re.search(pattern, message, re.IGNORECASE)
            if match:
                referenced = match.group(1)
                if not self._matches_current_patient(referenced):
                    return False, (
                        f"This conversation is about {self.current_name}. "
                        f"To ask about a different patient, please open their chart."
                    )

        return True, None

    def _matches_current_patient(self, reference: str) -> bool:
        reference = reference.lower().strip()
        # Check name match
        if reference in self.current_name or self.current_name in reference:
            return True
        # Check MRN match
        if reference == self.current_mrn:
            return True
        return False
```

